import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group, DoubleSide } from 'three/webgpu';
import { texture, uv, vec4, mix } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new Group();
  group.name = 'hub-collection-card-0-label';
  group.position.set(3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 1.6;
  const height = 1.0;
  const geometry = new PlaneGeometry(width, height);

  const material = new MeshBasicNodeMaterial();
  material.side = DoubleSide;
  material.transparent = true;

  let map = null;
  let disposed = false;

  try {
    map = ctx.textureLoader('/prism-mock/home/nodes/feature-card.png');
    if (map) {
      map.colorSpace = 'srgb';
      const texNode = texture(map, uv());
      const tint = vec4(0.086, 0.086, 0.114, 1.0);
      material.colorNode = mix(texNode, tint, 0.08);
    } else {
      material.colorNode = vec4(0.086, 0.086, 0.114, 1.0);
    }
  } catch (e) {
    material.colorNode = vec4(0.086, 0.086, 0.114, 1.0);
  }

  const mesh = new Mesh(geometry, material);
  mesh.name = 'collection-card-3-plane';
  group.add(mesh);

  const textMesh = ctx.fontAtlas.createText({
    text: 'Collection 3',
    font: 'display',
    weight: 400,
    size: 0.34,
    color: '#e8ecf2',
    align: 'center',
    anchor: 'center',
    maxWidth: width * 0.9
  });
  textMesh.name = 'collection-card-3-label-text';
  textMesh.position.set(0, 0, 0.01);
  group.add(textMesh);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
    if (textMesh.geometry) textMesh.geometry.dispose();
    if (textMesh.material) textMesh.material.dispose();
    group.userData.handlers = {};
  };

  return group;
}
